mapper.select:
SELECT DISTINCT permitted.node_id FROM ( SELECT t.in_node_id AS node_id FROM user_tunnel ut INNER JOIN tunnel t ON t.id = ut.tunnel_id WHERE ut.user_id = #{userId}
UNION ALL
SELECT ten.node_id AS node_id FROM user_tunnel ut INNER JOIN tunnel_entry_node ten ON ten.tunnel_id = ut.tunnel_id WHERE ut.user_id = #{userId}
UNION ALL
SELECT t.out_node_id AS node_id FROM user_tunnel ut INNER JOIN tunnel t ON t.id = ut.tunnel_id WHERE ut.user_id = #{userId} ) permitted WHERE permitted.node_id IS NOT NULL
